import osfrom pathlib import Pathfrom shutil import copy, copytreefrom sysconfig import get_pathfrom app.common.setting import VERSION# 1. activate virtual environment#    $ conda activate YOUR_ENV_NAME## 2. run deploy script#    $ python build.pyargs = [    'nuitka',    '--standalone',    '--onefile',    f'--output-filename=FofaView-v{VERSION}-win-amd64',    '--assume-yes-for-downloads',    '--msvc=latest',    '--windows-icon-from-ico=F:/FofaView/app/resource/images/icon.ico',    '--enable-plugins=pyqt6',    '--show-progress',    '--windows-company-name=Demonr',    '--windows-product-version=2.1.2',    '--windows-file-version=2.1.2',    '--windows-file-description="一款基于Python精心打造的图形界面化FOFA客户端"',    '--show-memory',    '--windows-disable-console',    '--output-dir=F:/FofaView/build',    'F:/FofaView/main.py']dist_folder = Path("F:/FofaView/build")copied_site_packages = []copied_standard_packages = []# run nuitka# https://blog.csdn.net/qq_25262697/article/details/129302819# https://www.cnblogs.com/happylee666/articles/16158458.htmlos.system(" ".join(args))# copy site-packages to dist foldersite_packages = Path(get_path('purelib'))for src in copied_site_packages:    src = site_packages / src    dist = dist_folder / src.name    print(f"Coping site-packages `{src}` to `{dist}`")    try:        if src.is_file():            copy(src, dist)        else:            copytree(src, dist)    except:        pass# copy standard libraryfor file in copied_standard_packages:    src = site_packages.parent / file    dist = dist_folder / src.name    print(f"Coping stand library `{src}` to `{dist}`")    try:        if src.is_file():            copy(src, dist)        else:            copytree(src, dist)    except:        pass